```ts
import type { GeospatialCamera } from "@babylonjs/lite";

export function centerOnLatLon(camera: GeospatialCamera, latitudeDeg: number, longitudeDeg: number): void {
    const R = camera.limits.planetRadius;
    const lat = (latitudeDeg * Math.PI) / 180;
    const lon = (longitudeDeg * Math.PI) / 180;

    const x = R * Math.cos(lat) * Math.cos(lon);
    const y = -R * Math.cos(lat) * Math.sin(lon);
    const z = R * Math.sin(lat);

    camera.center = { x, y, z };
}
```

I derived the Cartesian position from latitude/longitude using the coordinate convention in note 54 (north = +Z, east = −Y at the default centre on +X), so the centre is placed at `(R·cos φ·cos λ, −R·cos φ·sin λ, R·sin φ)` on the sphere of radius `camera.limits.planetRadius`. I assign a whole new object to `camera.center` (per note 11) so the camera re-orbits immediately, leaving yaw, pitch, and radius untouched. I'm confident in the coordinate mapping; the only minor uncertainty is whether `Vec3` might carry extra fields beyond `x`/`y`/`z` (its full definition isn't in the provided declarations), but the interface usage throughout the API treats it as a plain `{x, y, z}`.
